const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
const unitOf = currency => ZERO_DECIMAL.includes(currency) ? 1 : THREE_DECIMAL.includes(currency) ? 1000 : 100;
const day = ts => new Date(ts * 1000).toISOString().slice(0, 10);

// one message per batch: who didn't pay, how much, when Stripe tries again. nothing goes to Xero
const lines = $('Events').all().map(({ json: ev }) => {
  const inv = ev.payload.data.object;
  const currency = String(inv.currency).toUpperCase();
  const amount = new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(inv.amount_due / unitOf(currency));
  const who = [inv.customer_name, inv.customer_email].filter(Boolean).join(' ') || inv.customer;
  const next = inv.next_payment_attempt ? `next try ${day(inv.next_payment_attempt)}` : 'no retry scheduled';
  return `• ${who}: ${amount}, attempt ${inv.attempt_count}, ${next}\n  ${inv.hosted_invoice_url ?? inv.id}`;
});
const shown = lines.slice(0, 20);
if (lines.length > shown.length) shown.push(`…and ${lines.length - shown.length} more`);
return [{ json: { text: `Stripe: ${lines.length} failed payment${lines.length === 1 ? '' : 's'}\n${shown.join('\n')}` } }];
